package io.ecosync.chat;
import java.util.*;
import java.util.concurrent.*;
import java.time.Duration;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.core.io.ClassPathResource;
import org.springframework.ai.chat.messages.*;
import io.ecosync.organizations.TenantDirectory;
/** Owner-scoped durable work and explicit bounded model proposal loop. Single authority replica. */
@Service
public class ChatService {
 private final ChatKnowledge knowledge;private final JdbcTemplate db;private final TenantDirectory tenants;private final ChatCapabilities capabilities;private final ChatSettings settings;private final ObjectProvider<ModelPort> models;private final TransactionTemplate tx;private final String prompt;
 private final ExecutorService workers=new ThreadPoolExecutor(4,4,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(4),Thread.ofPlatform().daemon().name("chat-query-",0).factory(),new ThreadPoolExecutor.AbortPolicy());
 private final ExecutorService operations=new ThreadPoolExecutor(8,8,0,TimeUnit.MILLISECONDS,new SynchronousQueue<>(),Thread.ofPlatform().daemon().name("chat-operation-",0).factory(),new ThreadPoolExecutor.AbortPolicy());
 private final ScheduledExecutorService watchdog=Executors.newSingleThreadScheduledExecutor(Thread.ofPlatform().daemon().name("chat-deadline-",0).factory());
 private static final class Running {final QueryBudget budget;final UUID actor,org,conversation,turn;final int sequence;volatile Future<?> worker;volatile ChatCapabilities.Capability capability;volatile UUID execution;volatile boolean done;Running(QueryBudget b,UUID a,UUID o,UUID c,UUID t,int s){budget=b;actor=a;org=o;conversation=c;turn=t;sequence=s;}}
 private final ConcurrentMap<UUID,Running> running=new ConcurrentHashMap<>();
 public ChatService(JdbcTemplate db,TenantDirectory tenants,ChatCapabilities capabilities,ChatSettings settings,ObjectProvider<ModelPort> models,PlatformTransactionManager manager,ChatKnowledge knowledge){this.knowledge=knowledge;this.db=db;this.tenants=tenants;this.capabilities=capabilities;this.settings=settings;this.models=models;tx=new TransactionTemplate(manager);try{prompt=new ClassPathResource("prompts/chat-v1.txt").getContentAsString(java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Chat prompt unavailable");}db.update("UPDATE app.chat_turn SET status='INTERRUPTED',progress='Interrupted by platform restart',error_code='CHAT_INTERRUPTED',ended_at=CURRENT_TIMESTAMP WHERE status='RUNNING'");}
 public Map<String,Object> status(){ModelPort model=models.getIfAvailable();return Map.of("available",settings.enabled()&&model!=null,"provider",model==null?"disabled":model.provider(),"model",model==null?"":model.model(),"testDouble",model!=null&&model.testDouble(),"querySeconds",settings.seconds(),"toolCalls",settings.calls(),"message",settings.enabled()&&model!=null?model.testDouble()?"Verification test double; this is not an LLM.":"Local model configured; availability is checked when queried.":"AI is disabled or no local model is configured. Your integrations and conversation history remain available.");}
 private void membership(UUID actor,UUID org){tenants.requireMembership(actor,org);}
 private Map<String,Object> owner(UUID actor,UUID org,UUID id){membership(actor,org);var rows=db.queryForList("SELECT id,title,status,created_at,updated_at FROM app.chat_conversation WHERE organization_id=? AND id=? AND owner_id=?",org,id,actor);if(rows.size()!=1)throw new AccessDeniedException("Conversation unavailable");return rows.getFirst();}
 public Map<String,Object> create(UUID actor,UUID org,String title){membership(actor,org);if(title==null||title.isBlank()||title.length()>100||title.chars().anyMatch(Character::isISOControl))throw new ChatFailure("CHAT_INVALID_ARGUMENTS");UUID id=UUID.randomUUID();tx.executeWithoutResult(s->{db.execute("SELECT pg_advisory_xact_lock(33819006)");if(db.queryForObject("SELECT count(*) FROM app.chat_conversation WHERE organization_id=? AND owner_id=?",Integer.class,org,actor)>=64)throw new ChatFailure("CHAT_CONVERSATION_LIMIT");db.update("INSERT INTO app.chat_conversation(organization_id,id,owner_id,title) VALUES(?,?,?,?)",org,id,actor,title.strip());});return owner(actor,org,id);}
 public Map<String,Object> list(UUID actor,UUID org){membership(actor,org);return Map.of("items",db.queryForList("SELECT id,title,status,created_at,updated_at FROM app.chat_conversation WHERE organization_id=? AND owner_id=? ORDER BY updated_at DESC,id LIMIT 64",org,actor),"ai",status());}
 @SuppressWarnings("unchecked")
 public Map<String,Object> detail(UUID actor,UUID org,UUID id){var out=new LinkedHashMap<>(owner(actor,org,id));var turns=db.queryForList("SELECT id,status,progress,error_code,tool_calls,provider,model,prompt_version,dependencies::text,provenance::text,started_at,ended_at FROM app.chat_turn WHERE organization_id=? AND conversation_id=? AND owner_id=? ORDER BY started_at,id LIMIT 100",org,id,actor);var allowed=new HashMap<Object,Boolean>();for(var t:turns){boolean permitted=true;try{for(var c:(List<Map<String,Object>>)io.ecosync.restcontract.RestJson.MAPPER.readValue((String)t.remove("dependencies"),List.class))capabilities.current(actor,org,decode(c));}catch(Exception e){permitted=false;}allowed.put(t.get("id"),permitted);String provenance=(String)t.remove("provenance");t.put("provenance",permitted?io.ecosync.restcontract.RestJson.MAPPER.readValue(provenance,List.class):List.of());t.put("evidenceAccess",permitted?"CURRENT":"HIDDEN");}
  var messages=db.queryForList("SELECT id,turn_id,sequence,role,content,created_at FROM app.chat_message WHERE organization_id=? AND conversation_id=? AND owner_id=? ORDER BY sequence LIMIT 200",org,id,actor);for(var m:messages)if("ASSISTANT".equals(m.get("role"))&&!Boolean.TRUE.equals(allowed.get(m.get("turn_id"))))m.put("content","Source answer hidden because its current access or connector revision has changed.");out.put("messages",messages);out.put("turns",turns);out.put("ai",status());return out;
 }
 public Map<String,Object> archive(UUID actor,UUID org,UUID id){owner(actor,org,id);for(var r:running.values())if(r.conversation.equals(id)&&r.org.equals(org)&&r.actor.equals(actor))cancel(actor,org,id,r.turn);db.update("UPDATE app.chat_conversation SET status='ARCHIVED',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND owner_id=?",org,id,actor);return owner(actor,org,id);}
 public Map<String,Object> send(UUID actor,UUID org,UUID conversation,UUID request,String content){var budget=new QueryBudget(Duration.ofSeconds(settings.seconds()),settings.calls());owner(actor,org,conversation);if(request==null||content==null||content.isBlank()||content.length()>4000||content.indexOf(0)>=0)throw new ChatFailure("CHAT_INVALID_ARGUMENTS");String hash=ChatData.hash(List.of(conversation,content));var duplicate=db.queryForList("SELECT id,conversation_id,input_hash,status FROM app.chat_turn WHERE organization_id=? AND owner_id=? AND request_id=?",org,actor,request);if(!duplicate.isEmpty()){var row=duplicate.getFirst();if(!conversation.equals(row.get("conversation_id"))||!hash.equals(row.get("input_hash")))throw new ChatFailure("CHAT_REQUEST_REUSED");return Map.of("id",row.get("id"),"status",row.get("status"),"duplicate",true);}
  var model=models.getIfAvailable();if(!settings.enabled()||model==null)throw new ChatFailure("CHAT_AI_DISABLED");UUID turn=UUID.randomUUID();int sequence=tx.execute(s->{var rows=db.queryForList("SELECT next_sequence,status FROM app.chat_conversation WHERE organization_id=? AND id=? AND owner_id=? FOR UPDATE",org,conversation,actor);if(rows.size()!=1)throw new AccessDeniedException("Conversation unavailable");var row=rows.getFirst();int n=((Number)row.get("next_sequence")).intValue();if(!row.get("status").equals("OPEN"))throw new ChatFailure("CHAT_ARCHIVED");if(n>198)throw new ChatFailure("CHAT_CONVERSATION_LIMIT");if(db.queryForObject("SELECT count(*) FROM app.chat_turn WHERE organization_id=? AND conversation_id=? AND status='RUNNING'",Integer.class,org,conversation)>0)throw new ChatFailure("CHAT_BUSY");db.update("INSERT INTO app.chat_turn(organization_id,id,conversation_id,owner_id,request_id,input_hash,status,progress,provider,model,prompt_version) VALUES(?,?,?,?,?,?,'RUNNING','Discovering authorized capabilities',?,?,'1')",org,turn,conversation,actor,request,hash,model.provider(),model.model());db.update("INSERT INTO app.chat_message(organization_id,conversation_id,owner_id,id,turn_id,sequence,role,content) VALUES(?,?,?,?,?,?,'USER',?)",org,conversation,actor,UUID.randomUUID(),turn,n,content);db.update("UPDATE app.chat_conversation SET next_sequence=next_sequence+2,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",org,conversation);return n+1;});
  var r=new Running(budget,actor,org,conversation,turn,sequence);running.put(turn,r);try{r.worker=workers.submit(()->run(r,content,model));watchdog.schedule(()->{if(!r.done){finish(r,"TIMEOUT","The query reached its deadline. No later result will be delivered.","CHAT_TIMEOUT",List.of(),List.of());abort(r);}},settings.seconds(),TimeUnit.SECONDS);}catch(RejectedExecutionException e){finish(r,"FAILED","Chat capacity is busy. Try again later.","CHAT_BUSY",List.of(),List.of());running.remove(turn);}
  return Map.of("id",turn,"status","RUNNING","duplicate",false);
 }
 public Map<String,Object> cancel(UUID actor,UUID org,UUID conversation,UUID turn){owner(actor,org,conversation);if(db.queryForObject("SELECT count(*) FROM app.chat_turn WHERE organization_id=? AND id=? AND conversation_id=? AND owner_id=?",Integer.class,org,turn,conversation,actor)!=1)throw new AccessDeniedException("Query unavailable");var r=running.get(turn);if(r!=null){finish(r,"CANCELLED","Query cancelled. An already received remote request cannot be undone.","CHAT_CANCELLED",List.of(),List.of());abort(r);}return Map.of("cancelled",true);}
 private void abort(Running r){r.budget.cancel();if(r.worker!=null)r.worker.cancel(true);var cap=r.capability;var execution=r.execution;if(cap!=null&&execution!=null){try{operations.submit(()->capabilities.cancel(r.actor,r.org,cap,execution));}catch(RejectedExecutionException ignored){}}}
 private void live(Running r){r.budget.remaining();membership(r.actor,r.org);if(r.done||!"RUNNING".equals(db.queryForObject("SELECT status FROM app.chat_turn WHERE organization_id=? AND id=? AND owner_id=?",String.class,r.org,r.turn,r.actor)))throw new ChatFailure("CHAT_CANCELLED");}
 private <T>T bounded(Running r,Callable<T> action){live(r);Future<T> future;try{future=operations.submit(()->io.ecosync.execution.CallDeadline.within(r.budget.remaining(),action));}catch(RejectedExecutionException e){throw new ChatFailure("CHAT_BUSY");}try{return future.get(r.budget.remaining().toNanos(),TimeUnit.NANOSECONDS);}catch(TimeoutException e){throw new ChatFailure("CHAT_TIMEOUT");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new ChatFailure("CHAT_CANCELLED");}catch(ExecutionException e){if(e.getCause() instanceof RuntimeException x)throw x;throw new ChatFailure("CHAT_OPERATION_FAILED");}finally{future.cancel(true);}}
 private void progress(Running r,String text){live(r);db.update("UPDATE app.chat_turn SET progress=?,tool_calls=? WHERE organization_id=? AND id=? AND status='RUNNING'",text.substring(0,Math.min(100,text.length())),r.budget.calls(),r.org,r.turn);}
 private void run(Running r,String content,ModelPort model){var evidence=new ArrayList<ChatEvidence>();var dependencies=new ArrayList<ChatCapabilities.Capability>();try{
  live(r);var catalog=new ArrayList<>(capabilities.catalog(r.actor,r.org));catalog.addAll(knowledge.tools(catalog));var byName=new HashMap<String,ChatCapabilities.Capability>();catalog.forEach(c->byName.put(c.name(),c));var messages=new ArrayList<Message>();messages.add(new SystemMessage(prompt));
  // Only bounded owner user messages are reused; past source bodies/assistant claims are not model context.
  var history=db.queryForList("SELECT content FROM app.chat_message WHERE organization_id=? AND conversation_id=? AND owner_id=? AND role='USER' AND turn_id<>? ORDER BY sequence DESC LIMIT 6",String.class,r.org,r.conversation,r.actor,r.turn);Collections.reverse(history);for(String h:history)messages.add(new UserMessage(ChatData.clean(h).toString()));var previous=priorReferences(r);if(!previous.isEmpty())messages.add(new UserMessage("Untrusted references from earlier currently authorized turns; retrieve fresh source facts before answering: "+ChatData.json(previous)));messages.add(new UserMessage(ChatData.clean(content).toString()));var callIds=new HashSet<String>();
  for(int round=0;round<settings.rounds();round++){live(r);for(var c:dependencies)capabilities.current(r.actor,r.org,c);if(ChatData.bytes(messages.stream().map(m->m instanceof ToolResponseMessage t?(Object)t.getResponses():m instanceof AssistantMessage a?Map.of("text",Objects.toString(a.getText(),""),"calls",a.getToolCalls()):Map.of("role",m.getMessageType().getValue(),"content",Objects.toString(m.getText(),""))).toList())+ChatData.bytes(catalog.stream().map(ChatCapabilities.Capability::definition).toList())>settings.contextBytes())throw new ChatFailure("CHAT_CONTEXT_LIMIT");progress(r,"Understanding question and selecting authorized capabilities");AssistantMessage reply=bounded(r,()->model.propose(List.copyOf(messages),catalog,r.budget.remaining()));if(reply==null||ChatData.bytes(Map.of("text",Objects.toString(reply.getText(),""),"calls",reply.getToolCalls()))>8192)throw new ChatFailure("CHAT_INVALID_MODEL_RESPONSE");live(r);
   if(!reply.hasToolCalls()){complete(r,reply.getText(),evidence,dependencies);return;}if(reply.getToolCalls().size()>settings.calls()-r.budget.calls())throw new ChatFailure("CHAT_CALL_BUDGET");messages.add(reply);var responses=new ArrayList<ToolResponseMessage.ToolResponse>();
   for(var call:reply.getToolCalls()){live(r);if(call.id()==null||call.id().length()>128||!callIds.add(call.id())||!"function".equals(call.type()))throw new ChatFailure("CHAT_INVALID_MODEL_RESPONSE");var cap=byName.get(call.name());if(cap==null)throw new ChatFailure("CHAT_UNKNOWN_TOOL");var args=ChatData.object(call.arguments(),8192);if(!cap.kind().equals("DETERMINISTIC"))capabilities.current(r.actor,r.org,cap);r.budget.consume();progress(r,"Consulting "+cap.source());UUID execution=UUID.randomUUID();r.capability=cap;r.execution=execution;ChatEvidence item;
    try{if(cap.kind().equals("DETERMINISTIC")){Object value=switch(cap.name()){case "approved_mapping"->{var current=capabilities.catalog(r.actor,r.org);for(String key:List.of("sourceSystem","targetSystem")){var dependency=current.stream().filter(c->c.canonicalSource().equals(args.get(key))).findFirst().orElseThrow(()->new ChatFailure("CHAT_MAPPING_UNAVAILABLE"));if(!dependencies.contains(dependency))dependencies.add(dependency);}yield knowledge.mapping(args,current);}case "decimal_calculation"->knowledge.calculate(r.org,args,evidence);case "select_records"->knowledge.select(args,evidence);default->throw new ChatFailure("CHAT_UNKNOWN_TOOL");};item=new ChatEvidence("e"+(evidence.size()+1),cap,execution,"SUCCESS",value,value instanceof Map<?,?> selected&&Boolean.TRUE.equals(selected.get("truncated")));}else{var result=bounded(r,()->capabilities.invoke(r.actor,r.org,cap,execution,args));live(r);capabilities.current(r.actor,r.org,cap);item=ChatEvidence.success("e"+(evidence.size()+1),cap,execution,result,settings.evidenceBytes());dependencies.add(cap);}}catch(ChatFailure e){if(Set.of("CHAT_TIMEOUT","CHAT_CANCELLED").contains(e.code))try{operations.submit(()->capabilities.cancel(r.actor,r.org,cap,execution));}catch(RejectedExecutionException ignored){}throw e;}catch(AccessDeniedException e){throw new ChatFailure("CHAT_AUTHORITY_CHANGED");}catch(Exception e){item=new ChatEvidence("e"+(evidence.size()+1),cap,execution,code(e),Map.of(),false);}finally{r.capability=null;r.execution=null;}
    if(!cap.kind().equals("DETERMINISTIC")&&!dependencies.contains(cap))dependencies.add(cap);evidence.add(item);if(ChatData.bytes(evidence.stream().map(ChatEvidence::context).toList())>settings.evidenceBytes())throw new ChatFailure("CHAT_EVIDENCE_LIMIT");responses.add(new ToolResponseMessage.ToolResponse(call.id(),call.name(),ChatData.json(item.context())));
   }messages.add(ToolResponseMessage.builder().responses(responses).build());
  }throw new ChatFailure("CHAT_ROUND_BUDGET");
 }catch(Exception e){String code=code(e);String state=code.equals("CHAT_CANCELLED")?"CANCELLED":code.equals("CHAT_TIMEOUT")?"TIMEOUT":"FAILED";finish(r,state,"The query could not complete: "+code+". No unsupported answer was generated.",code,dependencies,provenance(r,evidence));}finally{r.done=true;running.remove(r.turn);}}
 @SuppressWarnings("unchecked")
 private void complete(Running r,String text,List<ChatEvidence> evidence,List<ChatCapabilities.Capability> dependencies){live(r);progress(r,"Preparing answer from verified evidence");var answer=ChatData.object(Objects.toString(text,""),8192);ChatData.keys(answer,Set.of("status","references","question"));String state=Objects.toString(answer.get("status"),"");if(!Set.of("COMPLETE","PARTIAL","AMBIGUOUS","CLARIFICATION_REQUIRED").contains(state)||!(answer.get("references") instanceof List<?> refs)||refs.size()>8)throw new ChatFailure("CHAT_UNGROUNDED_ANSWER");var lines=new ArrayList<String>();boolean partial=evidence.stream().anyMatch(e->!e.status().equals("SUCCESS")||e.truncated());var chosenReferences=new ArrayList<Map<String,Object>>();
  for(Object raw:refs){if(!(raw instanceof Map<?,?>))throw new ChatFailure("CHAT_INVALID_REFERENCE");var ref=(Map<String,Object>)raw;ChatData.keys(ref,Set.of("evidence","pointer"));var e=evidence.stream().filter(v->v.id().equals(ref.get("evidence"))&&v.status().equals("SUCCESS")).findFirst().orElseThrow(()->new ChatFailure("CHAT_INVALID_REFERENCE"));Object value=ChatData.pointer(e.data(),(String)ref.get("pointer"));String rendered=ChatData.json(value);if(rendered.length()>2000)throw new ChatFailure("CHAT_EVIDENCE_LIMIT");chosenReferences.add(ref);lines.add("["+e.id()+"] "+e.capability().source()+" / "+e.capability().operation()+" reports "+rendered+".");}
  var selectedSources=EvidenceGrounding.selected(chosenReferences,evidence);var sources=selectedSources.stream().map(e->e.capability().canonicalSource()).distinct().toList();
  if(lines.isEmpty()){if(!state.equals("CLARIFICATION_REQUIRED")||!(answer.get("question") instanceof String q)||q.isBlank()||q.length()>500||!q.endsWith("?"))throw new ChatFailure("CHAT_UNGROUNDED_ANSWER");lines.add("Clarification requested by the model: "+q);}else{if(sources.size()>1&&!knowledge.related(r.org,EvidenceGrounding.withMappings(selectedSources,evidence))){state="AMBIGUOUS";lines.add("These are source-local facts. No cross-system relationship has been verified for this answer.");}if(partial){state="PARTIAL";lines.add("This answer is partial: a source failed or returned truncated information.");}}
  for(var e:evidence)if(!e.status().equals("SUCCESS"))lines.add(e.capability().source()+": retrieval failed ("+e.status()+"); this does not mean an empty result.");for(var c:dependencies)capabilities.current(r.actor,r.org,c);live(r);finish(r,state,String.join("\n\n",lines),null,dependencies,provenance(r,evidence));
 }

 @SuppressWarnings("unchecked") private List<Object> priorReferences(Running r){var result=new ArrayList<Object>();var rows=db.queryForList("SELECT dependencies::text,provenance::text FROM app.chat_turn WHERE organization_id=? AND conversation_id=? AND owner_id=? AND id<>? AND status IN('COMPLETE','PARTIAL','AMBIGUOUS') ORDER BY started_at DESC LIMIT 3",r.org,r.conversation,r.actor,r.turn);for(var row:rows)try{for(var dep:(List<Map<String,Object>>)io.ecosync.restcontract.RestJson.MAPPER.readValue((String)row.get("dependencies"),List.class))capabilities.current(r.actor,r.org,decode(dep));Object refs=io.ecosync.restcontract.RestJson.MAPPER.readValue((String)row.get("provenance"),List.class);if(ChatData.bytes(refs)<=4096&&ChatData.bytes(result)+ChatData.bytes(refs)<=8192)result.add(refs);}catch(Exception ignored){/* revoked or revised references are excluded */}return result;}
 private List<Map<String,Object>> provenance(Running r,List<ChatEvidence> evidence){var result=new ArrayList<Map<String,Object>>();for(var e:evidence){var p=new LinkedHashMap<>(e.provenance());if(e.status().equals("SUCCESS")&&!e.capability().kind().equals("DETERMINISTIC")){var ids=knowledge.identifiers(r.org,e.capability(),e.data()).stream().filter(v->v.matches("[A-Za-z0-9_.:-]{1,100}")).sorted().toList();p.put("entityIdentifiers",ids.stream().limit(20).toList());p.put("referencesTruncated",ids.size()>20);}result.add(p);}if(ChatData.bytes(result)>16384)throw new ChatFailure("CHAT_EVIDENCE_LIMIT");return result;}
 private void finish(Running r,String state,String content,String error,List<ChatCapabilities.Capability> dependencies,List<Map<String,Object>> provenance){synchronized(r){if(r.done)return;tx.executeWithoutResult(s->{if(db.update("UPDATE app.chat_turn SET status=?,progress=?,error_code=?,tool_calls=?,dependencies=?::jsonb,provenance=?::jsonb,ended_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND owner_id=? AND status='RUNNING'",state,state,error,r.budget.calls(),ChatData.json(dependencies),ChatData.json(provenance),r.org,r.turn,r.actor)!=1)return;db.update("INSERT INTO app.chat_message(organization_id,conversation_id,owner_id,id,turn_id,sequence,role,content) VALUES(?,?,?,?,?,?,'ASSISTANT',?)",r.org,r.conversation,r.actor,UUID.randomUUID(),r.turn,r.sequence,content);db.update("UPDATE app.chat_conversation SET updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",r.org,r.conversation);});r.done=true;}}
 private static ChatCapabilities.Capability decode(Map<String,Object> c){return new ChatCapabilities.Capability((String)c.get("name"),(String)c.get("kind"),UUID.fromString(c.get("connector").toString()),UUID.fromString(c.get("entity").toString()),((Number)c.get("revision")).longValue(),(String)c.get("fingerprint"),(String)c.get("source"),(String)c.get("operation"),(Map<String,Object>)c.get("schema"),Objects.toString(c.get("canonicalSource"),"unverified:"+c.get("kind")+":"+c.get("connector")),Objects.toString(c.get("bindingFingerprint"),""));}
 private static String code(Exception e){if(e instanceof io.ecosync.execution.CallDeadline.Expired)return "CHAT_TIMEOUT";if(e instanceof ChatFailure c)return c.code;if(e instanceof io.ecosync.mcp.McpFailure m)return m.code();if(e instanceof io.ecosync.database.DatabaseFailure d)return d.code();if(e instanceof io.ecosync.restcontract.RestFailure f)return f.code;return "CHAT_OPERATION_FAILED";}
 @jakarta.annotation.PreDestroy public void close(){for(var r:running.values()){finish(r,"INTERRUPTED","Query interrupted by platform shutdown.","CHAT_INTERRUPTED",List.of(),List.of());abort(r);}workers.shutdownNow();operations.shutdownNow();watchdog.shutdownNow();}
}
